task = args["task"]
files = args["files"]
mt = get(args, "max_tokens", 8000)

if type(task) != "string" or len(task) == 0:
  error("working context: task must be a non-empty string")
if type(mt) != "int" or mt < 1:
  error("working context: max_tokens must be a positive integer")
if type(files) != "list" or len(files) == 0:
  error("working context: empty working set")

refs = []
seen_paths = []
for fe in files:
  if type(fe) != "map":
    error("working context: each file entry must be an object")
  if not has_key(fe, "path") or type(fe["path"]) != "string" or len(fe["path"]) == 0:
    error("working context: each file entry requires a non-empty string path")
  path = fe["path"]
  if path in seen_paths:
    error("working context: contradictory working set: duplicate path " + path)
  seen_paths = seen_paths + [path]
  role = ""
  if has_key(fe, "role"):
    if type(fe["role"]) != "string":
      error("working context: role must be a string for " + path)
    role = fe["role"]
  expand = []
  if has_key(fe, "expand"):
    if type(fe["expand"]) != "list":
      error("working context: expand must be a list for " + path)
    for e in fe["expand"]:
      if type(e) != "string":
        error("working context: expand entries must be strings for " + path)
      expand = expand + [e]
  syms = []
  if has_key(fe, "symbols"):
    if type(fe["symbols"]) != "list":
      error("working context: symbols must be a list for " + path)
    syms = fe["symbols"]
  if len(syms) == 0:
    ref = {f: path}
    if role != "":
      ref = merge(ref, {role: role})
    if len(expand) > 0:
      ref = merge(ref, {x: expand})
    refs = refs + [ref]
  else:
    seen_syms = []
    for sym in syms:
      if type(sym) != "string" or len(sym) == 0:
        error("working context: symbol must be a non-empty string for " + path)
      if sym in seen_syms:
        error("working context: contradictory working set: duplicate symbol " + sym + " in " + path)
      seen_syms = seen_syms + [sym]
      ref = {f: path, s: sym}
      if role != "":
        ref = merge(ref, {role: role})
      if len(expand) > 0:
        ref = merge(ref, {x: expand})
      refs = refs + [ref]

if len(refs) == 0:
  error("working context: empty working set")
if len(refs) > 128:
  error("working context: too many references (" + str(len(refs)) + "); maximum is 128")

res = lci.context(operation:"save", to_string:true, task:task, refs:refs)
json_parse(res["manifest"])

