manifest = args["manifest"]
mt = get(args, "max_tokens", 8000)

if type(manifest) != "string" or len(manifest) == 0:
  error("working context: manifest must be a non-empty string")
if type(mt) != "int" or mt < 1:
  error("working context: max_tokens must be a positive integer")
try:
  parsed = json_parse(manifest)
catch:
  error("working context: manifest is not valid JSON")
if type(parsed) != "map" or not has_key(parsed, "r") or type(parsed["r"]) != "list":
  error("working context: manifest must contain an r reference list")

refs = []
for ref in parsed["r"]:
  if type(ref) != "map":
    error("working context: manifest reference must be an object")
  if not has_key(ref, "f") or type(ref["f"]) != "string" or len(ref["f"]) == 0:
    error("working context: manifest reference requires a non-empty string f")
  clean = {f: ref["f"]}
  if has_key(ref, "s") and type(ref["s"]) == "string" and len(ref["s"]) > 0:
    clean = merge(clean, {s: ref["s"]})
  if has_key(ref, "role") and type(ref["role"]) == "string" and len(ref["role"]) > 0:
    clean = merge(clean, {role: ref["role"]})
  if has_key(ref, "x") and type(ref["x"]) == "list" and len(ref["x"]) > 0:
    clean = merge(clean, {x: ref["x"]})
  refs = refs + [clean]
if len(refs) == 0:
  error("working context: empty working set")
if len(refs) > 128:
  error("working context: too many references (" + str(len(refs)) + "); maximum is 128")

built = {t: get(parsed, "t", ""), v: "1.0", r: refs}
res = lci.context(operation:"load", from_string: json_stringify(built), max_tokens: mt)
if type(res) == "map":
  if has_key(res, "available") and res["available"] == false:
    error("working context: index unavailable: " + get(res, "reason", "") + " (" + get(res, "hint", "") + ")")
